bool StructTraits<::arc::mojom::FileInfo::DataView, ::arc::mojom::FileInfoPtr>::Read(
    ::arc::mojom::FileInfo::DataView input,
    ::arc::mojom::FileInfoPtr* output) {
  bool success = true;
  ::arc::mojom::FileInfoPtr result(::arc::mojom::FileInfo::New());
  
      if (success && !input.ReadContentUri(&result->content_uri))
        success = false;
      if (success && !input.ReadMimeType(&result->mime_type))
        success = false;
      if (success && !input.ReadName(&result->name))
        success = false;
      if (success)
        result->size = input.size();
  *output = std::move(result);
  return success;
}


